import { expect, test } from '@playwright/test';

test.use({ viewport: { width: 390, height: 844 } });

test('mobile navigation supports pointer, route, Escape, and focus flows', async ({ page }) => {
  await page.goto('/');
  const trigger = page.getByTestId('mobile-navigation-trigger');
  await expect(trigger).toBeVisible();
  await expect(trigger).toHaveAccessibleName('Open navigation menu');

  await trigger.click();
  const dialog = page.getByRole('dialog', { name: 'Site navigation' });
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole('link', { name: 'Research' })).toHaveAttribute('href', '/research');
  await expect(dialog.getByRole('link', { name: 'Docs' })).toHaveAttribute('href', '/docs');
  await expect(dialog.getByRole('link', { name: 'Changelog' })).toHaveAttribute('href', '/changelog');

  await page.keyboard.press('Escape');
  await expect(dialog).toBeHidden();
  await expect(trigger).toBeFocused();

  await trigger.click();
  await dialog.getByRole('link', { name: 'Docs' }).click();
  await expect(page).toHaveURL(/\/docs$/);
  await expect(page.getByRole('heading', { name: 'Docs' })).toBeVisible();
  await expect(page.getByRole('dialog', { name: 'Site navigation' })).toBeHidden();
  await expect(page.getByTestId('mobile-navigation-trigger')).toBeVisible();

  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  expect(overflow).toBe(false);
});

test('mobile navigation remains usable with reduced motion', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await page.goto('/research');
  await page.getByTestId('mobile-navigation-trigger').click();
  const dialog = page.getByRole('dialog', { name: 'Site navigation' });
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole('link', { name: 'Research' })).toHaveAttribute('aria-current', 'page');
});
